export async function search(filters: { active?: boolean; role?: string }) {
  const conds: any[] = []
  if (filters.active !== undefined) conds.push(sql`active = ${filters.active}`)
  if (filters.role) conds.push(sql`role = ${filters.role}`)
  const where = conds.length
    ? sql`WHERE ${conds.reduce((a, b) => sql`${a} AND ${b}`)}`
    : sql``
  return sql`SELECT * FROM users ${where}`
}

