export async function createOrderWithItems(sql, order, items) {
  return sql.begin(async ctx => {
    const [created] = await ctx`
      INSERT INTO orders (customer_id, total)
      VALUES (${order.customerId}, ${order.total})
      RETURNING id
    `;
    for (const item of items) {
      await ctx`
        INSERT INTO order_items (order_id, product_id, qty, price)
        VALUES (${created.id}, ${item.productId}, ${item.qty}, ${item.price})
      `;
    }
    return created.id;
  });
}

