export async function archiveOldRecords(sql, cutoff, batchSize) {
  return sql.begin(async ctx => {
    const moved = await ctx`
      INSERT INTO records_archive
      SELECT * FROM records
      WHERE created_at < ${cutoff}
      ORDER BY created_at ASC
      LIMIT ${batchSize}
      RETURNING id
    `;
    await ctx`
      DELETE FROM records
      WHERE id IN ${ctx(moved.map(r => r.id))}
    `;
    return moved.length;
  });
}

